"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["661346"],{138256(e){e.exports=JSON.parse('{"tag":{"label":"atf","permalink":"/sdk/4.13.0/tags/atf","allTagsPath":"/sdk/4.13.0/tags","count":5,"items":[{"id":"config/ci-integration","title":"CI Integration","description":"Guide for running the Now SDK in CI/CD pipelines: non-interactive authentication for now-sdk install, validating that keys.ts is committed via now-sdk build --frozenKeys, and the conventions that keep pipeline runs reproducible.","permalink":"/sdk/4.13.0/config/ci-integration"},{"id":"guides/atf-guide","title":"Implementing Tests Guide","description":"Create ServiceNow Automated Test Framework (ATF) test cases using Fluent APIs across 13 ATF categories: server, form, REST, catalog, email, app navigator, reporting, responsive dashboard, uiTestScript (custom UI), list and related list operations, and Service Portal variants (formSP, catalogSP). This guide covers test strategy, category selection, step configuration, and the full API surface for each ATF namespace.","permalink":"/sdk/4.13.0/guides/atf-guide"},{"id":"api/test-api","title":"Test","description":"Creates an Automated Test Framework test (sysatftest).","permalink":"/sdk/4.13.0/api/test-api"},{"id":"api/testsuite-api","title":"TestSuite","description":"Creates an Automated Test Framework test suite (sysatftest_suite) \u2014 a named, orderable collection of Test(...) records, optionally nested under a parent suite. This API is authoring only: it produces the suite/membership metadata, but does not trigger or schedule a run. Running a suite (on-demand, scheduled, or via CI/CD) is done through ATF\'s existing UI, scheduler, and CI/CD integration.","permalink":"/sdk/4.13.0/api/testsuite-api"},{"id":"guides/atf-ui-test-script-guide","title":"UI Test Script (TestingLibrary) Guide","description":"Author ATF tests for custom UI components using atf.uiTestScript.runTest() and the TestingLibrary API. Use this when a UI cannot be tested through the standard atf.form. or atf.catalog. steps \u2014 Angular/React widgets embedded in workspaces, custom SPAs or UI-page apps, and now-* web components. The test body runs in the client test runner with all API globals injected, so no imports are needed inside the script.","permalink":"/sdk/4.13.0/guides/atf-ui-test-script-guide"}],"unlisted":false}}')}}]);